package kw.urtv.shared;
import android.content.Context;import java.util.*;import java.text.Normalizer;import org.json.*;
/** Local dictionary plus country labels; unknown clubs use a phonetic Arabic fallback. */
public final class TeamNames {
 private static final Map<String,String> names=new HashMap<>();private static boolean ready;
 private static String key(String s){return Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}
 public static synchronized String arabic(Context c,String name){if(!ready){for(String code:Locale.getISOCountries())if(ContentPolicy.country(code)){Locale country=new Locale("",code);names.put(key(country.getDisplayCountry(Locale.ENGLISH)),country.getDisplayCountry(new Locale("ar")));}try(java.io.InputStream in=c.getAssets().open("football-names.json")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONObject j=new JSONObject(out.toString("UTF-8"));Iterator<String> keys=j.keys();while(keys.hasNext()){String k=keys.next();names.put(key(k),j.getString(k));}}catch(Exception ignored){}ready=true;}if(!ContentPolicy.text(name))return "";String found=names.get(key(name));if(found!=null)return found;if(name.matches(".*[\u0600-\u06ff].*"))return name;
 String s=Normalizer.normalize(name,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT);String[][] pairs={{"united","يونايتد"},{"city","سيتي"},{"town","تاون"},{"saint","سان"},{"sh","ش"},{"ch","تش"},{"th","ث"},{"ph","ف"},{"oo","و"},{"ee","ي"},{"ou","و"}};for(String[] p:pairs)s=s.replace(p[0],p[1]);String letters="abcdefghijklmnopqrstuvwxyz";String[] ar={"ا","ب","ك","د","ي","ف","ج","ه","ي","ج","ك","ل","م","ن","و","ب","ق","ر","س","ت","و","ف","و","كس","ي","ز"};StringBuilder out=new StringBuilder();for(char v:s.toCharArray()){int i=letters.indexOf(v);out.append(i<0?String.valueOf(v):ar[i]);}return out.toString();}
}
